import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"GDPR 的技术含义","description":"","frontmatter":{"title":"GDPR 的技术含义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gdpr-technical.md","filePath":"cs/gdpr-technical.md","lastUpdated":1789023840000}'),h={name:"cs/gdpr-technical.md"};function E(_,a,u,m,P,f){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="gdpr-的技术含义" tabindex="-1">GDPR 的技术含义 <a class="header-anchor" href="#gdpr-的技术含义" aria-label="Permalink to &quot;GDPR 的技术含义&quot;">​</a></h1><div class="epigraph"><p>GDPR 把个人数据的合法基础、目的限制、最小化、删除权写成义务。技术含义是：访问控制、留存、可删除架构、跨境、记录处理活动——不是贴合规徽章。</p><footer>—— Regulation (EU) 2016/679；对照 Article 29/EDPB 对技术措施的意见点名</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/k-anonymity">k-匿名</a>常被误当成合规完成。缺口是<strong>法律义务如何落到系统</strong>：最小化、目的、删除、安全适当。本课技术含义，不是法律咨询。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日志与备份让删除权变难。缺口是：数据图、加密与密钥销毁、留存工作流。</p><h3 id="适当安全" tabindex="-1">适当安全 <a class="header-anchor" href="#适当安全" aria-label="Permalink to &quot;适当安全&quot;">​</a></h3><p>第 32 条指向风险相应的技术。回到本课程的合同，而不是买一张证书。</p><p><span class="marginnote">GDPR 正文。脱敏下一课是最小化的工程手段。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列：合法基础记录、最小化字段、删除传播、违约通知时间。下一课脱敏与令牌化。</p>',12)),(e(),s(c,null,{default:r(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PURP%5B%22%E7%9B%AE%E7%9A%84%E9%99%90%E5%88%B6%22%5D%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%E5%8C%96%22%5D%0A%20%20MIN%20--%3E%20DEL%5B%22%E5%8F%AF%E5%88%A0%E9%99%A4%E6%9E%B6%E6%9E%84%22%5D%0A%20%20SEC%5B%22%E9%80%82%E5%BD%93%E5%AE%89%E5%85%A8%22%5D%20--%3E%20CTRL%5B%22%E6%9C%AC%E8%AF%BE%E7%A8%8B%E6%8E%A7%E5%88%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>法律把隐私当义务。令牌化下一课减少明文持有。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供规避法律的建议。脱敏与令牌化下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>k-匿名不是 GDPR 完成。</li><li>最小化、目的、删除要架构支持。</li><li>适当安全指向已讲控制。</li><li>下一课脱敏与令牌化。</li><li>出处：Regulation (EU) 2016/679。</li></ul>',8))])}const b=l(h,[["render",E]]);export{D as __pageData,b as default};
